package com.aerialfishingtracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(AerialFishingConfig.GROUP)
public interface AerialFishingConfig extends Config
{
    String GROUP = "aerialfishingtracker";

    @ConfigSection(name = "Catch rolls", description = "Successful cormorant returns; doubled fish do not add another rare-drop roll", position = 0)
    String CATCHES = "catches";

    @ConfigSection(name = "Molch pearls", description = "Only pearls earned by fishing", position = 1)
    String PEARLS = "pearls";

    @ConfigSection(name = "Pearl streaks", description = "Lifetime tracked streaks for this character", position = 2)
    String STREAKS = "streaks";

    @ConfigSection(name = "Golden tench", description = "Chance of at least one tench over the selected catches", position = 3)
    String TENCH = "tench";

    @ConfigSection(name = "Appearance", description = "Overlay appearance and session timeout", position = 4)
    String DISPLAY = "display";

    @ConfigSection(name = "Historical additions", description = "Add pre-tracker totals to the logged-in character", position = 5)
    String HISTORY = "history";

    @ConfigItem(keyName = "lifetimeCatches", name = "Lifetime fish", description = "Tracked successful returns plus historical fish; cleared only by explicit full reset", section = CATCHES, position = 0)
    default boolean lifetimeCatches() { return true; }

    @ConfigItem(keyName = "sessionCatches", name = "Sessions fish", description = "Successful returns this session; resets on client restart, manual reset, or after the configured idle time", section = CATCHES, position = 1)
    default boolean sessionCatches() { return true; }

    @ConfigItem(keyName = "sincePearl", name = "Rolls since pearl", description = "Successful returns since the last caught pearl; before the first pearl, counts from tracking start", section = CATCHES, position = 2)
    default boolean sincePearl() { return true; }

    @ConfigItem(keyName = "fishPerHour", name = "Fish per hour", description = "Session fish divided by elapsed time since the first catch, including idle time", section = CATCHES, position = 3)
    default boolean fishPerHour() { return true; }

    @ConfigItem(keyName = "sessionPearls", name = "Session pearls", description = "Pearls caught this session; excludes trades and pickups", section = PEARLS, position = 0)
    default boolean sessionPearls() { return true; }

    @ConfigItem(keyName = "lifetimePearls", name = "Lifetime pearls", description = "Tracked pearls plus historical pearls", section = PEARLS, position = 1)
    default boolean lifetimePearls() { return true; }

    @ConfigItem(keyName = "observedRate", name = "Actual pearl rate", description = "Lifetime fish divided by lifetime pearls, including historical additions", section = PEARLS, position = 2)
    default boolean observedRate() { return true; }

    @ConfigItem(keyName = "expectedRate", name = "Wiki pearl rate", description = "Estimated wiki rate using visible levels and the August 2026 approximately 50% increase", section = PEARLS, position = 3)
    default boolean expectedRate() { return true; }

    @ConfigItem(keyName = "pearlsPerHour", name = "Pearls per hour", description = "Session pearls divided by elapsed time since the first catch, including idle time", section = PEARLS, position = 4)
    default boolean pearlsPerHour() { return true; }

    @ConfigItem(keyName = "longestDry", name = "Longest dry", description = "Longest tracked pearl interval, including the ending pearl catch", section = STREAKS, position = 0)
    default boolean longestDry() { return true; }

    @ConfigItem(keyName = "shortestGap", name = "Most spooned", description = "Fewest fish between two caught pearls; unknown until two pearls", section = STREAKS, position = 1)
    default boolean shortestGap() { return true; }

    @ConfigItem(keyName = "tenches", name = "Golden tenches caught", description = "Lifetime tench items caught plus historical tenches; includes bonus duplicates", section = TENCH, position = 0)
    default boolean tenches() { return true; }

    @ConfigItem(keyName = "tenchChance", name = "Cumulative tench chance", description = "1 - (19999/20000)^catches. Each next catch remains 1/20,000", section = TENCH, position = 1)
    default boolean tenchChance() { return true; }

    @ConfigItem(keyName = "tenchScope", name = "Chance uses", description = "Lifetime includes historical catches; session excludes them. Catching a tench does not reset cumulative odds", section = TENCH, position = 2)
    default TenchScope tenchScope() { return TenchScope.LIFETIME; }

    @Range(min = 11, max = 22)
    @ConfigItem(keyName = "fontSize", name = "Font size", description = "RuneLite Plain 12 (p12_full) overlay font", section = DISPLAY, position = 0)
    default int fontSize() { return 15; }

    @Range(min = 0, max = 255)
    @ConfigItem(keyName = "backgroundOpacity", name = "Background opacity", description = "0 is transparent; 255 is opaque", section = DISPLAY, position = 1)
    default int backgroundOpacity() { return 160; }

    @Range(min = 1, max = 1440)
    @ConfigItem(keyName = "sessionTimeoutMinutes", name = "Session reset after (minutes)", description = "Start a new session after this many minutes without a successful aerial-fishing catch", section = DISPLAY, position = 2)
    default int sessionTimeoutMinutes() { return 15; }


    @ConfigItem(keyName = "historyFish", name = "Historical fish to add", description = "Fish caught before this tracker. Enter an amount, then enable Apply historical additions.", section = HISTORY, position = 0)
    default String historyFish() { return ""; }

    @ConfigItem(keyName = "historyPearls", name = "Historical pearls to add", description = "Optional pearls caught before this tracker.", section = HISTORY, position = 1)
    default String historyPearls() { return ""; }

    @ConfigItem(keyName = "historyTenches", name = "Historical tenches to add", description = "Optional Golden Tenches caught before this tracker.", section = HISTORY, position = 2)
    default String historyTenches() { return ""; }

    @ConfigItem(keyName = "applyHistorical", name = "Apply historical additions", description = "Enable after entering the amounts above. You will be asked to confirm the character and totals.", section = HISTORY, position = 3)
    default boolean applyHistorical() { return false; }

}

package com.aerialfishingtracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Skill;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.FontManager;

final class AerialFishingOverlay extends OverlayPanel
{
    static final Color PEARL = new Color(190, 255, 202);
    static final Color STREAK = new Color(184, 226, 255);
    static final Color TENCH = new Color(255, 188, 223);
    private final AerialFishingPlugin plugin;
    private final AerialFishingConfig config;
    private final Client client;
    private Font font;

    @Inject
    AerialFishingOverlay(AerialFishingPlugin plugin, AerialFishingConfig config, Client client)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(170, 0));
        panelComponent.setGap(new Point(0, 4));
        addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset session only", "Aerial Fishing Tracker",
            event -> plugin.resetSession(plugin.profile()));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.shouldDisplayOverlay() || plugin.stats() == null)
        {
            return null;
        }
        return renderStats(graphics, plugin.stats(), plugin.session(),
            client.getBoostedSkillLevel(Skill.FISHING), client.getBoostedSkillLevel(Skill.HUNTER), plugin.error());
    }

    // Package visibility allows the real renderer to be exercised headlessly.
    Dimension renderStats(Graphics2D graphics, FishingStats stats, FishingSession session, int fishing, int hunter, String error)
    {
        int size = Math.max(11, Math.min(22, config.fontSize()));
        if (font == null || font.getSize() != size)
        {
            font = FontManager.getRunescapeFont().deriveFont(Font.PLAIN, (float) size);
        }
        panelComponent.setBackgroundColor(new Color(23, 29, 36, Math.max(0, Math.min(255, config.backgroundOpacity()))));
        if (error != null)
        {
            row("Tracking paused", "Check sidebar", TENCH);
        }
        if (config.lifetimeCatches()) { row("Lifetime fish", number(stats.totalCatches()), Color.WHITE); }
        if (config.sessionCatches()) { row("Sessions fish", number(session.catches), Color.WHITE); }
        if (config.sincePearl()) { row("Rolls since pearl", number(stats.sincePearl), Color.WHITE); }
        long now = System.nanoTime();
        if (config.fishPerHour()) { row("Fish / hour", hourly(session.fishPerHour(now)), Color.WHITE); }
        if (config.sessionPearls()) { row("Session pearls", number(session.pearls), PEARL); }
        if (config.lifetimePearls()) { row("Lifetime pearls", number(stats.totalPearls()), PEARL); }
        if (config.observedRate())
        {
            double actual = stats.actualPearlDenominator();
            row("Actual pearl rate", Double.isNaN(actual) ? "--" : ratio(actual), PEARL);
        }
        if (config.expectedRate()) { row("Wiki pearl rate", ratio(FishingMath.estimatedPearlDenominator(fishing, hunter)), PEARL); }
        if (config.pearlsPerHour()) { row("Pearls / hour", hourly(session.pearlsPerHour(now)), PEARL); }
        if (config.longestDry()) { row("Longest dry", number(stats.longestDry), STREAK); }
        if (config.shortestGap()) { row("Most spooned", stats.shortestGap == 0 ? "--" : number(stats.shortestGap), STREAK); }
        if (config.tenches()) { row("Golden tenches", number(stats.totalTenches()), TENCH); }
        if (config.tenchChance())
        {
            boolean lifetime = config.tenchScope() == TenchScope.LIFETIME;
            double percent = 100 * FishingMath.tenchChance(lifetime ? stats.totalCatches() : session.catches);
            // Never round a non-certain event up to a displayed guarantee.
            String chance = percent >= 99.9999 ? ">99.9999%" : String.format(Locale.US, "%.4f%%", percent);
            row(lifetime ? "Tench odds (L)" : "Tench odds (S)", chance, TENCH);
        }
        if (panelComponent.getChildren().isEmpty())
        {
            return null;
        }
        Graphics2D copy = (Graphics2D) graphics.create();
        try
        {
            copy.setFont(font);
            return super.render(copy);
        }
        finally
        {
            copy.dispose();
        }
    }

    private void row(String label, String value, Color color)
    {
        panelComponent.getChildren().add(LineComponent.builder().left(label + ":").right(value)
            .leftColor(color).rightColor(color).leftFont(font).rightFont(font).build());
    }

    private static String number(long value) { return String.format(Locale.US, "%,d", value); }
    private static String ratio(double denominator) { return String.format(Locale.US, "1 / %.1f", denominator); }
    private static String hourly(double rate) { return Double.isNaN(rate) ? "--" : String.format(Locale.US, "%,.0f", rate); }
}

package com.aerialfishingtracker;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemQuantityChanged;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name = "Aerial Fishing Tracker", description = "Track aerial catches, pearl streaks and cumulative tench odds", tags = {"aerial", "fishing", "molch", "pearl", "tench"})
public class AerialFishingPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(AerialFishingPlugin.class);

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configManager;
    @Inject private AerialFishingConfig config;
    @Inject private StatsStore store;
    @Inject private OverlayManager overlayManager;
    @Inject private AerialFishingOverlay overlay;
    @Inject private ClientToolbar toolbar;

    // Retain sessions across logout, profile switches and plugin toggles within this client process.
    private final Map<String, FishingSession> sessions = new HashMap<>();
    private final CatchAccumulator pending = new CatchAccumulator();
    private String profile;
    private FishingStats stats;
    private FishingSession session;
    private int fishingXp = -1;
    private int hunterXp = -1;
    private int inventoryPearls = -1;
    private int inventoryTenches = -1;
    private boolean ready;
    private volatile boolean running;
    private volatile long lifecycle;
    private String error;
    private TrackerPanel panel;
    private NavigationButton navigation;

    @Provides
    AerialFishingConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(AerialFishingConfig.class);
    }

    @Override
    protected void startUp()
    {
        running = true;
        long generation = ++lifecycle;
        panel = new TrackerPanel(this);
        navigation = NavigationButton.builder().tooltip("Aerial Fishing Tracker").icon(icon()).priority(7).panel(panel).build();
        toolbar.addNavigation(navigation);
        overlayManager.add(overlay);
        clientThread.invoke(() ->
        {
            if (running && generation == lifecycle)
            {
                selectProfile();
                baseline();
                refreshPanel();
            }
        });
    }

    @Override
    protected void shutDown()
    {
        running = false;
        long generation = ++lifecycle;
        overlayManager.remove(overlay);
        toolbar.removeNavigation(navigation);
        clientThread.invoke(() ->
        {
            // Lifecycle methods run on the Swing EDT. Only the client thread may touch tracking
            // state; preserve a catch received after the last GameTick before disabling.
            completeCatch();
            if (generation == lifecycle)
            {
                ready = false;
            }
        });
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        clientThread.invoke(() ->
        {
            if (running)
            {
                selectProfile();
                baseline();
                refreshPanel();
            }
        });
    }

    private void selectProfile()
    {
        String next = configManager.getRSProfileKey();
        if (next == null || next.equals(profile))
        {
            return;
        }
        completeCatch();
        ready = false;
        profile = next;
        error = null;
        stats = null;
        session = sessions.computeIfAbsent(profile, key -> new FishingSession());
        session.expire(System.nanoTime(), sessionTimeoutNanos());
        try
        {
            stats = store.load(profile);
        }
        catch (RuntimeException ex)
        {
            fail(ex);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            // Flush a completed tick before a hop/logout; never interpret login inventory as loot.
            completeCatch();
            pending.clear();
            ready = false;
            fishingXp = -1;
            hunterXp = -1;
            inventoryPearls = -1;
            inventoryTenches = -1;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!running)
        {
            return;
        }
        selectProfile();
        if (!ready)
        {
            baseline();
        }
        else
        {
            completeCatch();
        }
        if (session != null)
        {
            session.expire(System.nanoTime(), sessionTimeoutNanos());
        }
        refreshPanel();
    }

    private void baseline()
    {
        pending.clear();
        ready = stats != null && client.getGameState() == GameState.LOGGED_IN
            && profile != null && profile.equals(configManager.getRSProfileKey());
        fishingXp = ready ? client.getSkillExperience(Skill.FISHING) : -1;
        hunterXp = ready ? client.getSkillExperience(Skill.HUNTER) : -1;
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        inventoryPearls = inventory == null ? -1 : inventory.count(ItemID.AERIAL_FISHING_PEARL);
        inventoryTenches = inventory == null ? -1 : inventory.count(ItemID.GOLDEN_TENCH);
    }

    private boolean canTrack()
    {
        return running && ready && error == null && client.getGameState() == GameState.LOGGED_IN
            && profile != null && profile.equals(configManager.getRSProfileKey()) && isFishingLocation();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!canTrack() || (event.getType() != ChatMessageType.SPAM && event.getType() != ChatMessageType.GAMEMESSAGE))
        {
            return;
        }
        String message = Text.removeTags(event.getMessage());
        if ("Your cormorant returns with its catch.".equals(message))
        {
            pending.catchSignal();
        }
        else if ("The cormorant has brought you a very strange tench.".equals(message))
        {
            pending.tenchMessage();
        }
        else if ("Untradeable drop: Molch pearl".equals(message))
        {
            pending.pearlMessage();
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (event.getSkill() != Skill.FISHING && event.getSkill() != Skill.HUNTER)
        {
            return;
        }
        boolean fishing = event.getSkill() == Skill.FISHING;
        int previous = fishing ? fishingXp : hunterXp;
        if (fishing) { fishingXp = event.getXp(); }
        else { hunterXp = event.getXp(); }
        // Require both fishing and hunter awards, avoiding a false catch from a one-skill XP
        // reward. If one skill is capped, use the other; if both are capped, use return chat.
        if (canTrack() && hasCormorant() && previous >= 0 && event.getXp() > previous && event.getXp() - previous <= 1000)
        {
            if (fishing)
            {
                pending.fishingXp();
                if (hunterXp == 200_000_000) { pending.hunterXp(); }
            }
            else
            {
                pending.hunterXp();
                if (fishingXp == 200_000_000) { pending.fishingXp(); }
            }
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INV)
        {
            return;
        }
        int pearls = event.getItemContainer().count(ItemID.AERIAL_FISHING_PEARL);
        int tenches = event.getItemContainer().count(ItemID.GOLDEN_TENCH);
        if (canTrack() && inventoryPearls >= 0 && inventoryTenches >= 0)
        {
            pending.inventory(pearls - inventoryPearls, tenches - inventoryTenches);
        }
        inventoryPearls = pearls;
        inventoryTenches = tenches;
    }

    @Subscribe
    public void onItemSpawned(ItemSpawned event)
    {
        groundReward(event.getItem(), event.getTile(), event.getItem().getQuantity());
    }

    @Subscribe
    public void onItemQuantityChanged(ItemQuantityChanged event)
    {
        groundReward(event.getItem(), event.getTile(), event.getNewQuantity() - event.getOldQuantity());
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event)
    {
        // An early removal can be an inventory pickup; natural expiry is not a transfer.
        if (event.getItem().getDespawnTime() > client.getTickCount())
        {
            groundReward(event.getItem(), event.getTile(), -event.getItem().getQuantity());
        }
    }

    private void groundReward(TileItem item, Tile tile, int quantity)
    {
        Player player = client.getLocalPlayer();
        if (canTrack() && player != null && item.getOwnership() == TileItem.OWNERSHIP_SELF
            && player.getWorldLocation().equals(tile.getWorldLocation()))
        {
            pending.ground(item.getId() == ItemID.AERIAL_FISHING_PEARL ? quantity : 0,
                item.getId() == ItemID.GOLDEN_TENCH ? quantity : 0);
        }
    }

    private void completeCatch()
    {
        CatchAccumulator.Result result = pending.finish();
        if (!result.caught || stats == null || error != null || profile == null)
        {
            return;
        }
        try
        {
            stats.recordCatch(result.pearl, result.tenches);
            session.recordCatch(System.nanoTime(), result.pearl, sessionTimeoutNanos());
            store.save(profile, stats);
        }
        catch (RuntimeException ex)
        {
            fail(ex);
        }
    }

    boolean isFishingLocation()
    {
        return isOnMolchIsland() || hasCormorant();
    }

    boolean shouldDisplayOverlay()
    {
        return isOnMolchIsland();
    }

    @Override
    public void resetConfiguration()
    {
        clientThread.invoke(() ->
        {
            String target = profile != null ? profile : configManager.getRSProfileKey();
            if (target == null) { return; }
            pending.clear();
            store.reset(target);
            if (target.equals(profile))
            {
                stats = new FishingStats();
                if (session != null) { session.reset(); }
                error = null;
            }
            overlayManager.resetOverlay(overlay);
            refreshPanel();
        });
    }

    private boolean isOnMolchIsland()
    {
        Player player = client.getLocalPlayer();
        if (player == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return false;
        }
        WorldPoint point = player.getWorldLocation();
        // RuneLite's own Discord area map identifies region 5432 as Molch Island.
        return point.getPlane() == 0 && point.getRegionID() == 5432;
    }

    private boolean hasCormorant()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        Item weapon = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        return weapon != null && (weapon.getId() == ItemID.AERIAL_FISHING_GLOVES_BIRD
            || weapon.getId() == ItemID.AERIAL_FISHING_GLOVES_NO_BIRD);
    }

    void resetSession(String expectedProfile)
    {
        clientThread.invoke(() ->
        {
            if (running && expectedProfile != null && expectedProfile.equals(profile) && canEdit())
            {
                completeCatch();
                session.reset();
                refreshPanel();
            }
        });
    }

    void addHistory(String expectedProfile, long catches, long pearls, long tenches)
    {
        clientThread.invoke(() ->
        {
            if (!running || expectedProfile == null || !expectedProfile.equals(profile) || !canEdit())
            {
                panel.showMessage("Character changed or is logged out. Nothing was added.");
                return;
            }
            try
            {
                stats.addHistory(catches, pearls, tenches);
            }
            catch (IllegalArgumentException | ArithmeticException ex)
            {
                panel.showMessage("Invalid amount or total too large. Nothing was added.");
                return;
            }
            try
            {
                store.save(profile, stats);
                panel.showMessage("Historical counts added to this character.");
                refreshPanel();
            }
            catch (RuntimeException ex)
            {
                fail(ex);
            }
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!AerialFishingConfig.GROUP.equals(event.getGroup()) || !"applyHistorical".equals(event.getKey())
            || !Boolean.parseBoolean(event.getNewValue()) || panel == null)
        {
            return;
        }

        // Reset the switch immediately so an accidental revisit cannot apply the same additions twice.
        configManager.setConfiguration(AerialFishingConfig.GROUP, "applyHistorical", false);
        panel.confirmHistoryFromSettings(config.historyFish(), config.historyPearls(), config.historyTenches());
    }

    void clearHistorySettings()
    {
        configManager.setConfiguration(AerialFishingConfig.GROUP, "historyFish", "");
        configManager.setConfiguration(AerialFishingConfig.GROUP, "historyPearls", "");
        configManager.setConfiguration(AerialFishingConfig.GROUP, "historyTenches", "");
    }

    private long sessionTimeoutNanos()
    {
        return FishingSession.timeoutNanos(config.sessionTimeoutMinutes());
    }

    private boolean canEdit()
    {
        return stats != null && error == null && client.getGameState() == GameState.LOGGED_IN
            && profile != null && profile.equals(configManager.getRSProfileKey());
    }

    private void fail(RuntimeException ex)
    {
        error = "Tracking paused: saved data needs attention. See client log; lifetime data was not reset.";
        LOG.error("Aerial Fishing Tracker stopped to protect lifetime data", ex);
        refreshPanel();
    }

    private void refreshPanel()
    {
        if (panel != null)
        {
            Player player = client.getLocalPlayer();
            String name = canEdit() && player != null ? player.getName() : "Log in to edit this character";
            panel.update(profile, name, stats == null ? 0 : stats.totalCatches(), canEdit(), error);
        }
    }

    FishingStats stats() { return stats; }
    FishingSession session() { return session; }
    String error() { return error; }
    String profile() { return profile; }

    private static BufferedImage icon()
    {
        BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setColor(new Color(158, 226, 177));
        graphics.fillOval(3, 7, 15, 10);
        graphics.fillPolygon(new int[]{16, 23, 23}, new int[]{12, 5, 19}, 3);
        graphics.setColor(new Color(25, 30, 36));
        graphics.fillOval(6, 10, 3, 3);
        graphics.dispose();
        return image;
    }
}

package com.aerialfishingtracker;

/** Reconciles signals from one server tick. Bonus items never create extra tench rolls. */
final class CatchAccumulator
{
    private boolean caught;
    private boolean fishingXp;
    private boolean hunterXp;
    private boolean pearlMessage;
    private int tenchMessage;
    private long inventoryPearls;
    private long inventoryTenches;
    private long groundPearls;
    private long groundTenches;

    void catchSignal() { caught = true; }
    void fishingXp() { fishingXp = true; }
    void hunterXp() { hunterXp = true; }
    void pearlMessage() { pearlMessage = true; }
    void tenchMessage() { caught = true; tenchMessage = 1; }

    void inventory(int pearls, int tenches)
    {
        inventoryPearls += pearls;
        inventoryTenches += tenches;
    }

    void ground(int pearls, int tenches)
    {
        groundPearls += pearls;
        groundTenches += tenches;
    }

    Result finish()
    {
        // Moving old loot between ground and inventory has net zero gain. A tench trade/refund
        // has a bulk pearl gain, never the single pearl produced by one successful catch.
        long pearls = inventoryPearls + groundPearls;
        long tenches = inventoryTenches + groundTenches;
        // Rada's blessing and spirit flakes add independent chances to double the selected
        // catch, but their reward quantity is capped at two items.
        int tenchItems = tenches >= 1 && tenches <= 2 ? (int) tenches : 0;
        Result result = new Result(caught || (fishingXp && hunterXp), pearlMessage || pearls == 1,
            Math.max(tenchMessage, tenchItems));
        clear();
        return result;
    }

    void clear()
    {
        caught = false;
        fishingXp = false;
        hunterXp = false;
        pearlMessage = false;
        tenchMessage = 0;
        inventoryPearls = 0;
        inventoryTenches = 0;
        groundPearls = 0;
        groundTenches = 0;
    }

    static final class Result
    {
        final boolean caught;
        final boolean pearl;
        final int tenches;

        Result(boolean caught, boolean pearl, int tenches)
        {
            this.caught = caught;
            this.pearl = pearl;
            this.tenches = tenches;
        }
    }
}

package com.aerialfishingtracker;

final class FishingMath
{
    private FishingMath() { }

    static double tenchChance(long catches)
    {
        if (catches < 0)
        {
            throw new IllegalArgumentException("Negative catch count");
        }
        return -Math.expm1(catches * Math.log1p(-1.0 / 20_000.0));
    }

    // Wiki formula uses integer X = ((Fishing * 2) + Hunter) / 3.
    static double estimatedPearlDenominator(int fishing, int hunter)
    {
        int level = (2 * fishing + hunter) / 3;
        // Approximation for the August 2026 ~50% pearl chance increase.
        return (100.0 - ((level - 40.0) * 25.0 / 59.0)) / 1.5;
    }
}

package com.aerialfishingtracker;

import java.time.Duration;

final class FishingSession
{
    static final int DEFAULT_TIMEOUT_MINUTES = 15;
    long catches;
    long pearls;
    private long firstCatch;
    private long lastCatch;
    private boolean active;
    private static final long RATE_REFRESH_NANOS = Duration.ofSeconds(5).toNanos();
    private long lastRateRefresh;
    private boolean ratesInitialized;
    private double displayedFishRate = Double.NaN;
    private double displayedPearlRate = Double.NaN;

    static long timeoutNanos(int minutes)
    {
        return Duration.ofMinutes(Math.max(1, Math.min(1440, minutes))).toNanos();
    }

    void expire(long now, long timeoutNanos)
    {
        if (active && now - lastCatch >= timeoutNanos)
        {
            reset();
        }
    }

    void recordCatch(long now, boolean pearl, long timeoutNanos)
    {
        expire(now, timeoutNanos);
        if (!active)
        {
            firstCatch = now;
        }
        catches++;
        if (pearl)
        {
            pearls++;
        }
        lastCatch = now;
        active = true;
    }

    void reset()
    {
        catches = 0;
        pearls = 0;
        firstCatch = 0;
        lastCatch = 0;
        active = false;
        ratesInitialized = false;
        displayedFishRate = Double.NaN;
        displayedPearlRate = Double.NaN;
    }

    double fishPerHour(long now)
    {
        refreshRates(now);
        return displayedFishRate;
    }

    double pearlsPerHour(long now)
    {
        refreshRates(now);
        return displayedPearlRate;
    }

    private void refreshRates(long now)
    {
        if (!active || catches < 2 || now - firstCatch <= 0) { return; }
        if (ratesInitialized && now - lastRateRefresh < RATE_REFRESH_NANOS) { return; }
        displayedFishRate = perHour(catches, now);
        displayedPearlRate = perHour(pearls, now);
        lastRateRefresh = now;
        ratesInitialized = true;
    }

    private double perHour(long amount, long now)
    {
        long elapsed = now - firstCatch;
        if (!active || catches < 2 || elapsed <= 0)
        {
            return Double.NaN;
        }
        return (double) amount * Duration.ofHours(1).toNanos() / elapsed;
    }
}

package com.aerialfishingtracker;

/** Persistent data only. There is deliberately no reset method. */
final class FishingStats
{
    private static final int CURRENT_SCHEMA = 2;
    int schema = CURRENT_SCHEMA;
    long catches;
    long pearls;
    long tenches;
    long historicalCatches;
    long historicalPearls;
    long historicalTenches;
    long sincePearl;
    long longestDry;
    long shortestGap;
    boolean seenPearl;

    void recordCatch(boolean pearl, int tenchItems)
    {
        if (tenchItems < 0 || tenchItems > 2)
        {
            throw new IllegalArgumentException("Invalid tench drop quantity");
        }
        long nextCatches = Math.addExact(catches, 1);
        long nextTenches = Math.addExact(tenches, tenchItems);
        long nextPearls = Math.addExact(pearls, pearl ? 1 : 0);
        long interval = Math.addExact(sincePearl, 1);
        Math.addExact(nextCatches, historicalCatches);
        Math.addExact(nextTenches, historicalTenches);
        Math.addExact(nextPearls, historicalPearls);
        catches = nextCatches;
        tenches = nextTenches;
        pearls = nextPearls;
        if (pearl)
        {
            longestDry = Math.max(longestDry, interval);
            if (seenPearl && (shortestGap == 0 || interval < shortestGap))
            {
                shortestGap = interval;
            }
            seenPearl = true;
            sincePearl = 0;
        }
        else
        {
            sincePearl = interval;
            longestDry = Math.max(longestDry, sincePearl);
        }
    }

    void addHistory(long fish, long pearl, long tench)
    {
        if (fish < 0 || pearl < 0 || tench < 0)
        {
            throw new IllegalArgumentException("Historical amounts must be non-negative.");
        }
        // Validate every addition before changing any field.
        long nextFish = Math.addExact(historicalCatches, fish);
        long nextPearl = Math.addExact(historicalPearls, pearl);
        long nextTench = Math.addExact(historicalTenches, tench);
        Math.addExact(catches, nextFish);
        Math.addExact(pearls, nextPearl);
        Math.addExact(tenches, nextTench);
        historicalCatches = nextFish;
        historicalPearls = nextPearl;
        historicalTenches = nextTench;
    }

    long totalCatches() { return Math.addExact(catches, historicalCatches); }
    long totalPearls() { return Math.addExact(pearls, historicalPearls); }
    long totalTenches() { return Math.addExact(tenches, historicalTenches); }
    double actualPearlDenominator()
    {
        long total = totalPearls();
        return total == 0 ? Double.NaN : totalCatches() / (double) total;
    }

    void migrate()
    {
        if (schema == 1)
        {
            // Schema 1 counted only failed rolls for completed dry streaks, while shortestGap
            // included the ending pearl. Repair completed legacy streaks without adding a roll
            // to a currently unfinished run that is already the longest.
            if (seenPearl && longestDry > 0 && sincePearl < longestDry)
            {
                longestDry = Math.addExact(longestDry, 1);
            }
            longestDry = Math.max(longestDry, shortestGap);
            schema = CURRENT_SCHEMA;
        }
    }

    void validate()
    {
        if (schema != CURRENT_SCHEMA || catches < 0 || pearls < 0 || tenches < 0 || historicalCatches < 0
            || historicalPearls < 0 || historicalTenches < 0 || sincePearl < 0 || longestDry < sincePearl
            || shortestGap < 0 || pearls > catches || sincePearl > catches || longestDry > catches
            || shortestGap > catches || seenPearl != (pearls > 0))
        {
            throw new IllegalArgumentException("Invalid or unsupported lifetime data; refusing to overwrite it.");
        }
        totalCatches();
        totalPearls();
        totalTenches();
    }
}

package com.aerialfishingtracker;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.math.BigInteger;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

final class StatsStore
{
    private static final BigInteger MAX_LONG = BigInteger.valueOf(Long.MAX_VALUE);
    // Separate from visible preferences: only the explicit, confirmed full reset clears statistics.
    static final String GROUP = "aerialfishingtrackerdata";
    static final String KEY = "lifetimeV1";
    static final String BACKUP = "lifetimeBackupV1";
    private final ConfigManager configManager;
    private final Gson gson;

    @Inject
    StatsStore(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    FishingStats load(String profile)
    {
        requireProfile(profile);
        String json = configManager.getConfiguration(GROUP, profile, KEY);
        if (json == null)
        {
            json = configManager.getConfiguration(GROUP, profile, BACKUP);
        }
        return json == null ? new FishingStats() : decode(json);
    }

    void save(String profile, FishingStats stats)
    {
        requireProfile(profile);
        stats.validate();
        String previous = configManager.getConfiguration(GROUP, profile, KEY);
        if (previous == null)
        {
            previous = configManager.getConfiguration(GROUP, profile, BACKUP);
        }
        if (previous != null)
        {
            FishingStats prior = decode(previous);
            if (stats.catches < prior.catches || stats.pearls < prior.pearls || stats.tenches < prior.tenches
                || stats.historicalCatches < prior.historicalCatches || stats.historicalPearls < prior.historicalPearls
                || stats.historicalTenches < prior.historicalTenches)
            {
                throw new IllegalStateException("Refusing to reduce saved lifetime totals.");
            }
        }
        String json = gson.toJson(stats);
        configManager.setConfiguration(GROUP, profile, KEY, json);
        configManager.setConfiguration(GROUP, profile, BACKUP, json);
    }

    void reset(String profile)
    {
        requireProfile(profile);
        configManager.unsetConfiguration(GROUP, profile, KEY);
        configManager.unsetConfiguration(GROUP, profile, BACKUP);
    }

    private FishingStats decode(String json)
    {
        JsonObject object = gson.fromJson(json, JsonObject.class);
        String[] required = {"schema", "catches", "pearls", "tenches", "historicalCatches", "historicalPearls",
            "historicalTenches", "sincePearl", "longestDry", "shortestGap", "seenPearl"};
        for (String key : required)
        {
            if (object == null || !object.has(key) || object.get(key).isJsonNull())
            {
                throw new IllegalArgumentException("Incomplete saved statistics; refusing to replace them.");
            }
            if (!object.get(key).isJsonPrimitive()
                || ("seenPearl".equals(key) ? !object.getAsJsonPrimitive(key).isBoolean()
                : !object.getAsJsonPrimitive(key).isNumber() || !object.get(key).getAsString().matches("[0-9]+")))
            {
                throw new IllegalArgumentException("Invalid saved statistic type; refusing to replace it.");
            }
            if (!"seenPearl".equals(key)
                && new BigInteger(object.get(key).getAsString()).compareTo(MAX_LONG) > 0)
            {
                throw new IllegalArgumentException("Saved statistic is too large; refusing to replace it.");
            }
        }
        FishingStats result = gson.fromJson(object, FishingStats.class);
        result.migrate();
        result.validate();
        return result;
    }

    private static void requireProfile(String profile)
    {
        if (profile == null || profile.isEmpty())
        {
            throw new IllegalArgumentException("A character profile is required.");
        }
    }
}

