package com.aerialfishingtracker;

import org.junit.Test;
import static org.junit.Assert.*;

public class FishingMathTest
{
    @Test
    public void tenchProbabilityMatchesIndependentReferenceValues()
    {
        assertEquals(0, FishingMath.tenchChance(0), 0);
        assertEquals(0.00005, FishingMath.tenchChance(1), 1e-16);
        assertEquals(0.632129756, FishingMath.tenchChance(20000), 1e-9);
        assertEquals(0.55068002267, FishingMath.tenchChance(16000), 1e-11);
        assertEquals(1, FishingMath.tenchChance(Long.MAX_VALUE), 0);
        assertThrows(IllegalArgumentException.class, () -> FishingMath.tenchChance(-1));
    }

    @Test
    public void probabilityIsMonotonic()
    {
        double previous = 0;
        for (long n = 1; n < 100000; n += 37)
        {
            double chance = FishingMath.tenchChance(n);
            assertTrue(chance >= previous && chance <= 1);
            previous = chance;
        }
    }

    @Test
    public void pearlEstimateUsesWeightedBoostedLevels()
    {
        assertEquals(50, FishingMath.estimatedPearlDenominator(99, 99), 1e-12);
        assertEquals(200.0 / 3.0, FishingMath.estimatedPearlDenominator(43, 35), 1e-12);
        // X uses integer division in the game formula.
        assertEquals(FishingMath.estimatedPearlDenominator(43, 35),
            FishingMath.estimatedPearlDenominator(43, 36), 1e-12);
        assertTrue(FishingMath.estimatedPearlDenominator(104, 102) < 50);
        assertTrue(FishingMath.estimatedPearlDenominator(90, 80) < FishingMath.estimatedPearlDenominator(80, 90));
    }
}

package com.aerialfishingtracker;

import org.junit.Test;
import static org.junit.Assert.*;

public class FishingSessionTest
{
    @Test
    public void displayedRatesStayFixedUntilFiveSecondsAndIncludeNewCatches()
    {
        long second = java.time.Duration.ofSeconds(1).toNanos();
        long timeout = FishingSession.timeoutNanos(15);
        FishingSession session = new FishingSession();
        session.recordCatch(0, false, timeout);
        session.recordCatch(10 * second, true, timeout);
        assertEquals(720.0, session.fishPerHour(10 * second), 0.0);
        assertEquals(360.0, session.pearlsPerHour(10 * second), 0.0);
        session.recordCatch(12 * second, true, timeout);
        assertEquals(720.0, session.fishPerHour(15 * second - 1), 0.0);
        assertEquals(360.0, session.pearlsPerHour(15 * second - 1), 0.0);
        assertEquals(480.0, session.pearlsPerHour(15 * second), 0.0);
        assertEquals(720.0, session.fishPerHour(15 * second), 0.0);
        assertEquals(540.0, session.fishPerHour(20 * second), 0.0);
        session.reset();
        assertTrue(Double.isNaN(session.fishPerHour(20 * second)));
        assertTrue(Double.isNaN(session.pearlsPerHour(20 * second)));
    }

    @Test
    public void hourlyRatesUseSessionTimeAndResetWithSession()
    {
        long hour = java.time.Duration.ofHours(1).toNanos();
        long timeout = FishingSession.timeoutNanos(120);
        FishingSession session = new FishingSession();
        assertTrue(Double.isNaN(session.fishPerHour(0)));
        session.recordCatch(0, true, timeout);
        assertTrue(Double.isNaN(session.pearlsPerHour(1)));
        session.recordCatch(hour, false, timeout);
        assertEquals(2.0, session.fishPerHour(hour), 0.0);
        assertEquals(1.0, session.pearlsPerHour(hour), 0.0);
        assertEquals(1.0, session.fishPerHour(2 * hour), 0.0);
        session.reset();
        assertTrue(Double.isNaN(session.fishPerHour(2 * hour)));
        session.recordCatch(3 * hour, false, timeout);
        session.recordCatch(4 * hour, false, timeout);
        assertEquals(2.0, session.fishPerHour(4 * hour), 0.0);
        assertEquals(0.0, session.pearlsPerHour(4 * hour), 0.0);
        session.expire(6 * hour, timeout);
        assertTrue(Double.isNaN(session.fishPerHour(6 * hour)));
    }

    @Test
    public void exactConfiguredTimeoutBoundary()
    {
        long timeout = FishingSession.timeoutNanos(15);
        FishingSession session = new FishingSession();
        session.recordCatch(0, true, timeout);
        session.expire(timeout - 1, timeout);
        assertEquals(1, session.catches);
        session.expire(timeout, timeout);
        assertEquals(0, session.catches);
        assertEquals(0, session.pearls);
    }

    @Test
    public void firstCatchAfterIdleStartsNewSessionAndIsIncluded()
    {
        FishingSession session = new FishingSession();
        long timeout = FishingSession.timeoutNanos(15);
        session.recordCatch(0, true, timeout);
        session.recordCatch(timeout, false, timeout);
        assertEquals(1, session.catches);
        assertEquals(0, session.pearls);
    }

    @Test
    public void everyCatchExtendsSessionAndResetOnlyTouchesSession()
    {
        FishingSession session = new FishingSession();
        long timeout = FishingSession.timeoutNanos(15);
        FishingStats stats = new FishingStats();
        stats.recordCatch(true, 1);
        session.recordCatch(0, true, timeout);
        session.recordCatch(timeout - 1, false, timeout);
        session.expire(timeout + 1, timeout);
        assertEquals(2, session.catches);
        session.reset();
        assertEquals(0, session.catches);
        assertEquals(1, stats.totalCatches());
        assertEquals(1, stats.totalPearls());
    }

    @Test
    public void timeoutClampsToSafeMinuteRange()
    {
        assertEquals(FishingSession.timeoutNanos(1), FishingSession.timeoutNanos(0));
        assertEquals(FishingSession.timeoutNanos(1440), FishingSession.timeoutNanos(2000));
    }


}

package com.aerialfishingtracker;

import org.junit.Test;
import static org.junit.Assert.*;

public class FishingStatsTest
{
    @Test
    public void countsCatchesAndCompletePearlIntervalsWithoutOffByOne()
    {
        FishingStats stats = new FishingStats();
        stats.recordCatch(false, 0);
        stats.recordCatch(false, 0);
        assertEquals(2, stats.longestDry);
        stats.recordCatch(true, 0);
        assertEquals(3, stats.longestDry);
        assertEquals(0, stats.sincePearl);
        assertEquals(0, stats.shortestGap); // first observed interval has an unknown starting point
        stats.recordCatch(false, 0);
        stats.recordCatch(true, 0);
        assertEquals(2, stats.shortestGap);
        stats.recordCatch(true, 0);
        assertEquals(1, stats.shortestGap);
        assertEquals(6, stats.catches);
        assertEquals(3, stats.pearls);
        stats.validate();
    }

    @Test
    public void historyChangesLifetimeTotalsWithoutChangingTrackedStreaks()
    {
        FishingStats stats = new FishingStats();
        stats.recordCatch(true, 2);
        stats.recordCatch(false, 0);
        stats.addHistory(10000, 500, 3);
        assertEquals(10002, stats.totalCatches());
        assertEquals(501, stats.totalPearls());
        assertEquals(5, stats.totalTenches());
        assertEquals(10002.0 / 501.0, stats.actualPearlDenominator(), 0.0);
        assertEquals(2, stats.catches);
        assertEquals(1, stats.pearls);
        assertEquals(1, stats.sincePearl);
        assertEquals(0, stats.shortestGap);
    }

    @Test
    public void historyIsAdditiveAndRejectsNegativeOrOverflowAtomically()
    {
        FishingStats stats = new FishingStats();
        stats.addHistory(40, 1, 0);
        stats.addHistory(20, 2, 1);
        assertEquals(60, stats.totalCatches());
        assertThrows(IllegalArgumentException.class, () -> stats.addHistory(-1, 0, 0));
        assertThrows(ArithmeticException.class, () -> stats.addHistory(4, Long.MAX_VALUE, 0));
        assertEquals(60, stats.totalCatches());
        assertEquals(3, stats.totalPearls());
    }

    @Test
    public void actualPearlRateIncludesHistory()
    {
        FishingStats stats = new FishingStats();
        stats.addHistory(16000, 0, 0);
        assertTrue(Double.isNaN(stats.actualPearlDenominator()));
        stats.addHistory(0, 200, 0);
        assertEquals(80.0, stats.actualPearlDenominator(), 0.0);
    }

    @Test
    public void overflowingCatchCannotPartiallyMutateLifetime()
    {
        FishingStats stats = new FishingStats();
        stats.addHistory(Long.MAX_VALUE, 0, 0);
        assertThrows(ArithmeticException.class, () -> stats.recordCatch(true, 1));
        assertEquals(0, stats.catches);
        assertEquals(0, stats.pearls);
        assertEquals(0, stats.tenches);
    }

    @Test
    public void longestDryIncludesAnUnfinishedRun()
    {
        FishingStats stats = new FishingStats();
        stats.recordCatch(true, 0);
        for (int i = 0; i < 500; i++) { stats.recordCatch(false, 0); }
        assertEquals(500, stats.longestDry);
        stats.recordCatch(true, 0);
        assertEquals(501, stats.longestDry);
        assertEquals(501, stats.shortestGap);
    }
}

package com.aerialfishingtracker;

import java.lang.reflect.Field;
