import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Regression cases written independently after the implementation's first passing build. */
public class IndependentCriticTest
{
    @Test
    public void disablingBetweenCompletionAndTickMustPreserveTheCompletedCatch() throws Exception
    {
        AerialFishingPlugin plugin = new AerialFishingPlugin();
        Client client = mock(Client.class);
        ConfigManager config = mock(ConfigManager.class);
        StatsStore store = mock(StatsStore.class);
        ClientThread thread = mock(ClientThread.class);
        doAnswer(invocation -> { ((Runnable) invocation.getArgument(0)).run(); return null; })
            .when(thread).invoke(any(Runnable.class));
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(config.getRSProfileKey()).thenReturn("critic");
        when(store.load("critic")).thenReturn(new FishingStats());
        field(plugin, "client", client);
        field(plugin, "clientThread", thread);
        field(plugin, "configManager", config);
        field(plugin, "config", new AerialFishingConfig() { });
        field(plugin, "store", store);
        field(plugin, "toolbar", mock(ClientToolbar.class));
        field(plugin, "overlayManager", mock(OverlayManager.class));
        plugin.startUp();
        CatchAccumulator pending = (CatchAccumulator) field(plugin, "pending");
        pending.catchSignal();
        plugin.shutDown();
        plugin.startUp();
        plugin.onGameTick(new GameTick());
        assertEquals("Already-completed catches must survive a plugin toggle", 1, plugin.stats().catches);
        verify(store).save("critic", plugin.stats());
    }

    @Test
    public void separateGroundTenchItemsFromOneBonusCatchBothCount()
    {
        CatchAccumulator pending = new CatchAccumulator();
        pending.catchSignal();
        pending.tenchMessage();
        pending.ground(0, 1);
        pending.ground(0, 1);
        CatchAccumulator.Result result = pending.finish();
        assertTrue(result.caught);
        assertEquals("Two distinct nonstackable ground items are two tench items", 2, result.tenches);
    }

    @Test
    public void interleavedSeparateInventoryTenchGainsBothCount()
    {
        CatchAccumulator pending = new CatchAccumulator();
        pending.catchSignal();
        pending.inventory(0, 1);
        pending.inventory(0, 1);
        assertEquals("Two positive deltas in one catch tick represent two awarded items", 2, pending.finish().tenches);
    }

    @Test
    public void pickingUpOldPearlDuringCatchDoesNotProduceNewPearl()
    {
        CatchAccumulator pending = new CatchAccumulator();
        pending.catchSignal();
        pending.ground(-1, 0);
        pending.inventory(1, 0);
        assertFalse("A transfer of existing loot does not improve pearl streaks", pending.finish().pearl);
    }

    @Test
    public void droppingOldTenchDuringCatchDoesNotProduceNewTench()
    {
        CatchAccumulator pending = new CatchAccumulator();
        pending.catchSignal();
        pending.inventory(0, -1);
        pending.ground(0, 1);
        assertEquals("Dropping an existing tench does not earn another tench", 0, pending.finish().tenches);
    }

    @Test
    public void immediatePickupOfFreshGroundTenchIsCountedOnce()
    {
        CatchAccumulator pending = new CatchAccumulator();
        pending.catchSignal();
        pending.ground(0, 1);
        pending.ground(0, -1);
        pending.inventory(0, 1);
        assertEquals("Fresh loot changing containers is one reward", 1, pending.finish().tenches);
    }

    @Test
    public void backupPreservesLatestSnapshotWhenPrimaryKeyIsMissing()
    {
        ConfigManager config = mock(ConfigManager.class);
        java.util.Map<String, String> values = new java.util.HashMap<>();
        when(config.getConfiguration(anyString(), anyString(), anyString()))
            .thenAnswer(call -> values.get(call.getArgument(2)));
        doAnswer(call -> { values.put(call.getArgument(2), call.getArgument(3)); return null; })
            .when(config).setConfiguration(anyString(), anyString(), anyString(), anyString());
        StatsStore store = new StatsStore(config, new com.google.gson.Gson());
        FishingStats stats = new FishingStats();
        stats.recordCatch(false, 0);
        store.save("critic", stats);
        stats.recordCatch(false, 0);
        store.save("critic", stats);
        values.remove(StatsStore.KEY);
        assertEquals("Recovery should not silently reduce lifetime catches", 2, store.load("critic").catches);
    }

    @Test
    public void outOfRangeSavedIntegerMustNotWrapIntoAnEmptyLifetime()
    {
        ConfigManager config = mock(ConfigManager.class);
        String json = new com.google.gson.Gson().toJson(new FishingStats())
            .replace("\"catches\":0", "\"catches\":18446744073709551616");
        when(config.getConfiguration(StatsStore.GROUP, "critic", StatsStore.KEY)).thenReturn(json);
        StatsStore store = new StatsStore(config, new com.google.gson.Gson());
        assertThrows(RuntimeException.class, () -> store.load("critic"));
    }

    private static void field(Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Object field(Object target, String name) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }
}

package com.aerialfishingtracker;

import java.lang.reflect.Field;
import java.util.ArrayDeque;
import java.util.Queue;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Independent event-level and deferred-lifecycle checks, not live server observations. */
public class IndependentEventTest
{
    private final Queue<Runnable> callbacks = new ArrayDeque<>();
    private final AerialFishingPlugin plugin = new AerialFishingPlugin();
    private final Client client = mock(Client.class);
    private final ConfigManager config = mock(ConfigManager.class);
    private final StatsStore store = mock(StatsStore.class);
    private final ItemContainer inventory = mock(ItemContainer.class);
    private final WorldPoint position = new WorldPoint(1368, 3633, 0);

    @Before
    public void initialize() throws Exception
    {
        ClientThread thread = mock(ClientThread.class);
        doAnswer(call -> { callbacks.add(call.getArgument(0)); return null; })
            .when(thread).invoke(any(Runnable.class));
        Player player = mock(Player.class);
        when(player.getWorldLocation()).thenReturn(position);
        when(client.getLocalPlayer()).thenReturn(player);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getTickCount()).thenReturn(100);
        when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
        when(config.getRSProfileKey()).thenReturn("critic");
        when(store.load("critic")).thenReturn(new FishingStats());
        inject("client", client);
        inject("clientThread", thread);
        inject("configManager", config);
        inject("config", new AerialFishingConfig() { });
        inject("store", store);
        inject("toolbar", mock(ClientToolbar.class));
        inject("overlayManager", mock(OverlayManager.class));
        plugin.startUp();
        drainCallbacks();
    }

    @Test
    public void naturalPearlExpiryDoesNotCancelFreshInventoryReward()
    {
        caught();
        when(inventory.count(ItemID.AERIAL_FISHING_PEARL)).thenReturn(1);
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventory));
        plugin.onItemDespawned(new ItemDespawned(tile(), pearl(100)));
        plugin.onGameTick(new GameTick());
        assertEquals(1, plugin.stats().pearls);
    }

    @Test
    public void earlyPearlDespawnAndInventoryGainAreOnlyAPickup()
    {
        caught();
        when(inventory.count(ItemID.AERIAL_FISHING_PEARL)).thenReturn(1);
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventory));
        plugin.onItemDespawned(new ItemDespawned(tile(), pearl(200)));
        plugin.onGameTick(new GameTick());
        assertEquals(1, plugin.stats().catches);
        assertEquals(0, plugin.stats().pearls);
    }

    @Test
    public void freshGroundPearlThenImmediatePickupCountsOnce()
    {
        caught();
        Tile tile = tile();
        TileItem pearl = pearl(200);
        plugin.onItemSpawned(new ItemSpawned(tile, pearl));
        plugin.onItemDespawned(new ItemDespawned(tile, pearl));
        when(inventory.count(ItemID.AERIAL_FISHING_PEARL)).thenReturn(1);
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventory));
        plugin.onGameTick(new GameTick());
        assertEquals(1, plugin.stats().pearls);
    }

    @Test
    public void rapidDisableEnableKeepsQueuedCatchExactlyOnce()
    {
        caught();
        plugin.shutDown();
        plugin.startUp();
        assertEquals(0, plugin.stats().catches);
        drainCallbacks();
        assertEquals(1, plugin.stats().catches);
        caught();
        plugin.onGameTick(new GameTick());
        assertEquals(2, plugin.stats().catches);
        assertEquals(2, plugin.session().catches);
        verify(store, times(2)).save("critic", plugin.stats());
    }

    @Test
    public void staleStartupDoesNotUndoFinalShutdown() throws Exception
    {
        plugin.shutDown();
        plugin.startUp();
        plugin.shutDown();
        drainCallbacks();
        Field ready = AerialFishingPlugin.class.getDeclaredField("ready");
        ready.setAccessible(true);
        assertFalse(ready.getBoolean(plugin));
        caught();
        plugin.onGameTick(new GameTick());
        assertEquals(0, plugin.stats().catches);
    }

    private void caught()
    {
        plugin.onChatMessage(new ChatMessage(null, ChatMessageType.SPAM, "",
            "Your cormorant returns with its catch.", "", 0));
    }

    private Tile tile()
    {
        Tile tile = mock(Tile.class);
        when(tile.getWorldLocation()).thenReturn(position);
        return tile;
    }

    private TileItem pearl(int despawnTick)
    {
        TileItem pearl = mock(TileItem.class);
        when(pearl.getId()).thenReturn(ItemID.AERIAL_FISHING_PEARL);
        when(pearl.getQuantity()).thenReturn(1);
        when(pearl.getOwnership()).thenReturn(TileItem.OWNERSHIP_SELF);
        when(pearl.getDespawnTime()).thenReturn(despawnTick);
        return pearl;
    }

    private void drainCallbacks()
    {
        while (!callbacks.isEmpty()) { callbacks.remove().run(); }
    }

    private void inject(String name, Object value) throws Exception
    {
        Field field = AerialFishingPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

package com.aerialfishingtracker;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import static org.mockito.Mockito.mock;
import net.runelite.api.Client;

public final class OverlayPreview
{
    private OverlayPreview() { }

    public static void main(String[] args) throws Exception
    {
        AerialFishingOverlay overlay = new AerialFishingOverlay(new AerialFishingPlugin(), new AerialFishingConfig() { }, mock(Client.class));
        FishingStats stats = new FishingStats();
        for (int i = 1; i <= 532; i++)
        {
            stats.recordCatch(i % 43 == 0, 0);
        }
        stats.addHistory(10000, 130, 0);
        FishingSession session = new FishingSession();
        long timeout = FishingSession.timeoutNanos(15);
        for (int i = 0; i < 80; i++) { session.recordCatch(i, i % 30 == 0, timeout); }
        BufferedImage image = new BufferedImage(320, 330, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.translate(12, 12);
        // RuneLite PanelComponent measures children on its first frame, then paints the measured background.
        overlay.renderStats(graphics, stats, session, 91, 85, null);
        graphics.setComposite(java.awt.AlphaComposite.Clear);
        graphics.fillRect(0, 0, image.getWidth(), image.getHeight());
        graphics.setComposite(java.awt.AlphaComposite.SrcOver);
        overlay.renderStats(graphics, stats, session, 91, 85, null);
        graphics.dispose();
        File output = new File("build/overlay-preview.png");
        if (!output.getParentFile().isDirectory() && !output.getParentFile().mkdirs())
        {
            throw new IllegalStateException("Cannot create output directory");
        }
        ImageIO.write(image, "png", output);
    }
}

